package net.civeira.phylax.feature.observe.observabilityconfig.application.usecase.update;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfigChangeSet;

class ObservabilityConfigUpdateInputUnitTest {

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the observability config input values are kept when converted to a change set and back")
  void test_observability_config_update_input_change_set_round_trip() {
    ObservabilityConfigUpdateInput input = ObservabilityConfigUpdateInput.builder().uid("one")
        .code("one").retentionDaysLogs(1).retentionDaysTraces(1).retentionDaysErrors(1)
        .retentionDaysMetrics(1).retentionDaysMetricsRollup(1).retentionHoursDebug(1)
        .retentionHoursInfo(1).retentionHoursWarn(1).retentionHoursError(1).maxDiskMb(1)
        .scrubFields("one").labelDenylist("one").captureRequestBody(true).version(1).build();
    ObservabilityConfigChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    ObservabilityConfigUpdateInput copy = ObservabilityConfigUpdateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getCode().isPresent(), "code must be assigned by the builder");
    Assertions.assertEquals(input.getCode(), copy.getCode(),
        "code must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionDaysLogs().isPresent(),
        "retentionDaysLogs must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionDaysLogs(), copy.getRetentionDaysLogs(),
        "retentionDaysLogs must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionDaysTraces().isPresent(),
        "retentionDaysTraces must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionDaysTraces(), copy.getRetentionDaysTraces(),
        "retentionDaysTraces must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionDaysErrors().isPresent(),
        "retentionDaysErrors must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionDaysErrors(), copy.getRetentionDaysErrors(),
        "retentionDaysErrors must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionDaysMetrics().isPresent(),
        "retentionDaysMetrics must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionDaysMetrics(), copy.getRetentionDaysMetrics(),
        "retentionDaysMetrics must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionDaysMetricsRollup().isPresent(),
        "retentionDaysMetricsRollup must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionDaysMetricsRollup(),
        copy.getRetentionDaysMetricsRollup(),
        "retentionDaysMetricsRollup must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionHoursDebug().isPresent(),
        "retentionHoursDebug must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionHoursDebug(), copy.getRetentionHoursDebug(),
        "retentionHoursDebug must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionHoursInfo().isPresent(),
        "retentionHoursInfo must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionHoursInfo(), copy.getRetentionHoursInfo(),
        "retentionHoursInfo must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionHoursWarn().isPresent(),
        "retentionHoursWarn must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionHoursWarn(), copy.getRetentionHoursWarn(),
        "retentionHoursWarn must survive the change set round trip");
    Assertions.assertTrue(input.getRetentionHoursError().isPresent(),
        "retentionHoursError must be assigned by the builder");
    Assertions.assertEquals(input.getRetentionHoursError(), copy.getRetentionHoursError(),
        "retentionHoursError must survive the change set round trip");
    Assertions.assertTrue(input.getMaxDiskMb().isPresent(),
        "maxDiskMb must be assigned by the builder");
    Assertions.assertEquals(input.getMaxDiskMb(), copy.getMaxDiskMb(),
        "maxDiskMb must survive the change set round trip");
    Assertions.assertTrue(input.getScrubFields().isPresent(),
        "scrubFields must be assigned by the builder");
    Assertions.assertEquals(input.getScrubFields(), copy.getScrubFields(),
        "scrubFields must survive the change set round trip");
    Assertions.assertTrue(input.getLabelDenylist().isPresent(),
        "labelDenylist must be assigned by the builder");
    Assertions.assertEquals(input.getLabelDenylist(), copy.getLabelDenylist(),
        "labelDenylist must survive the change set round trip");
    Assertions.assertTrue(input.getCaptureRequestBody().isPresent(),
        "captureRequestBody must be assigned by the builder");
    Assertions.assertEquals(input.getCaptureRequestBody(), copy.getCaptureRequestBody(),
        "captureRequestBody must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the observability config input builder can generate a new identifier")
  void test_observability_config_update_input_new_uid() {
    ObservabilityConfigUpdateInput input =
        ObservabilityConfigUpdateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        ObservabilityConfigUpdateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated UpdateInputGenerator
   */
  @Test
  @DisplayName("Test the observability config input starts empty and the setters assign values")
  void test_observability_config_update_input_setters() {
    ObservabilityConfigUpdateInput empty = ObservabilityConfigUpdateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getCode().isEmpty(), "code must be empty by default");
    Assertions.assertSame(empty, empty.setCode("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCode().isPresent(), "code must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionDaysLogs().isEmpty(),
        "retentionDaysLogs must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionDaysLogs(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionDaysLogs().isPresent(),
        "retentionDaysLogs must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionDaysTraces().isEmpty(),
        "retentionDaysTraces must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionDaysTraces(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionDaysTraces().isPresent(),
        "retentionDaysTraces must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionDaysErrors().isEmpty(),
        "retentionDaysErrors must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionDaysErrors(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionDaysErrors().isPresent(),
        "retentionDaysErrors must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionDaysMetrics().isEmpty(),
        "retentionDaysMetrics must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionDaysMetrics(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionDaysMetrics().isPresent(),
        "retentionDaysMetrics must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionDaysMetricsRollup().isEmpty(),
        "retentionDaysMetricsRollup must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionDaysMetricsRollup(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionDaysMetricsRollup().isPresent(),
        "retentionDaysMetricsRollup must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionHoursDebug().isEmpty(),
        "retentionHoursDebug must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionHoursDebug(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionHoursDebug().isPresent(),
        "retentionHoursDebug must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionHoursInfo().isEmpty(),
        "retentionHoursInfo must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionHoursInfo(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionHoursInfo().isPresent(),
        "retentionHoursInfo must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionHoursWarn().isEmpty(),
        "retentionHoursWarn must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionHoursWarn(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionHoursWarn().isPresent(),
        "retentionHoursWarn must be assigned by the setter");
    Assertions.assertTrue(empty.getRetentionHoursError().isEmpty(),
        "retentionHoursError must be empty by default");
    Assertions.assertSame(empty, empty.setRetentionHoursError(1),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRetentionHoursError().isPresent(),
        "retentionHoursError must be assigned by the setter");
    Assertions.assertTrue(empty.getMaxDiskMb().isEmpty(), "maxDiskMb must be empty by default");
    Assertions.assertSame(empty, empty.setMaxDiskMb(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getMaxDiskMb().isPresent(),
        "maxDiskMb must be assigned by the setter");
    Assertions.assertTrue(empty.getScrubFields().isEmpty(), "scrubFields must be empty by default");
    Assertions.assertSame(empty, empty.setScrubFields("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getScrubFields().isPresent(),
        "scrubFields must be assigned by the setter");
    Assertions.assertTrue(empty.getLabelDenylist().isEmpty(),
        "labelDenylist must be empty by default");
    Assertions.assertSame(empty, empty.setLabelDenylist("one"),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLabelDenylist().isPresent(),
        "labelDenylist must be assigned by the setter");
    Assertions.assertTrue(empty.getCaptureRequestBody().isEmpty(),
        "captureRequestBody must be empty by default");
    Assertions.assertSame(empty, empty.setCaptureRequestBody(true),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getCaptureRequestBody().isPresent(),
        "captureRequestBody must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
